<?php
 namespace Pterodactyl\Http\Requests\Api\Client\Servers\Players; use Pterodactyl\Models\Permission; class PlayerActionRequest extends PlayerRequest { public function permission(): string { return Permission::ACTION_CONTROL_CONSOLE; } public function rules(): array { return [ 'action' => 'required|string|in:op,ban,whitelist,gamemode,kill,heal,feed,starve,teleport,xp', 'on' => 'sometimes|boolean', 'mode' => 'sometimes|string|in:survival,creative,adventure,spectator', 'x' => 'sometimes|numeric|between:-30000000,30000000', 'y' => 'sometimes|numeric|between:-512,1024', 'z' => 'sometimes|numeric|between:-30000000,30000000', 'dimension' => 'sometimes|string|in:minecraft:overworld,minecraft:the_nether,minecraft:the_end', 'levels' => 'sometimes|integer|between:0,24791', 'operation' => 'sometimes|string|in:set,add,remove', ]; } } 